-- Thế giới khối vuông của bước Nhập vai (21/11/2026). Người dùng chọn: 3D nhìn chéo, chỉ thay bước Nhập vai, làm trọn bản đồ phần 3 (1287–1288) trước,
-- bạn cùng lớp chơi chung trực tuyến. Mỗi lớp có một phòng cho mỗi cuộc kháng chiến; khối học sinh đặt trong vùng xây dựng (cọc, rào, thuyền, bao lương)
-- là của cả phòng và được giữ lại. Túi đồ và tiến độ nhiệm vụ vẫn nằm trong phiên chơi sẵn có (hk_saga_sessions, kind = 'explore').
--  - hk_saga_maps.world: bản đồ khối (lưới ô, nhân vật, bàn chế tạo, vùng) – nội dung mẫu, kiểm tra bằng normalizeWorldMap (backend/src/saga/world.ts).
--  - hk_saga_stages.content.world: nhiệm vụ của 4 chặng phần 3 (chuan-bi-1287, van-don, van-kiep-1288, bach-dang); cảnh 2D cũ (content.explore) giữ nguyên.
--  - hk_world_rooms / hk_world_blocks: dữ liệu của lớp, RLS theo trường như các bảng hk_* khác, không cấp quyền công khai.
-- Dữ kiện lịch sử trong lời thoại lấy từ thẻ kiến thức / tổng kết đã có nguồn của các chặng (migration 066); nhân vật phụ, lời thoại, công thức, số lượng là
-- phần sáng tạo của trò chơi. Không đổi dữ liệu học sinh hiện có.

ALTER TABLE public.hk_saga_maps ADD COLUMN IF NOT EXISTS world JSONB CHECK (world IS NULL OR jsonb_typeof(world) = 'object');

CREATE TABLE public.hk_world_rooms (
    id SERIAL PRIMARY KEY,
    class_id INTEGER NOT NULL REFERENCES public.app_classes(id) ON DELETE CASCADE,
    campaign_no SMALLINT NOT NULL REFERENCES public.hk_saga_maps(campaign_no) ON DELETE CASCADE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (class_id, campaign_no)
);

-- Một ô một khối (x, z trên lưới của bản đồ khối). Vùng đầy thì dịch vụ dời khối cũ nhất sang ô mới (UPDATE), không xóa.
CREATE TABLE public.hk_world_blocks (
    room_id INTEGER NOT NULL REFERENCES public.hk_world_rooms(id) ON DELETE CASCADE,
    x SMALLINT NOT NULL CHECK (x BETWEEN 0 AND 199),
    z SMALLINT NOT NULL CHECK (z BETWEEN 0 AND 199),
    block TEXT NOT NULL CHECK (block ~ '^[a-z_]{2,20}$'),
    zone TEXT NOT NULL CHECK (zone ~ '^[a-z0-9_]{1,24}$'),
    user_id INTEGER REFERENCES public.app_users(id) ON DELETE SET NULL,
    placed_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (room_id, x, z)
);
CREATE INDEX hk_world_blocks_zone_idx ON public.hk_world_blocks(room_id, zone, placed_at);

DO $$
DECLARE t TEXT; own TEXT; rule TEXT; r TEXT;
BEGIN
    FOREACH t IN ARRAY ARRAY['hk_world_rooms', 'hk_world_blocks']
    LOOP
        EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
        EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC', t);
        FOREACH r IN ARRAY ARRAY['anon', 'authenticated', 'service_role'] LOOP
            IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) THEN EXECUTE format('REVOKE ALL ON public.%I FROM %I', t, r); END IF;
        END LOOP;
        own := format('public.app_workspace_owner(%L::regclass, to_jsonb(%I))', 'public.' || t, t);
        rule := format('((public.app_workspace_school() IS NOT NULL AND %s = public.app_workspace_school()) OR %s = -NULLIF(current_setting(''app.user_id'', true), '''')::integer)', own, own);
        EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO dong_a_workspace_scope', t);
        EXECUTE format('CREATE POLICY workspace_read ON public.%I FOR SELECT TO dong_a_workspace_scope USING (%s)', t, rule);
        EXECUTE format('CREATE POLICY workspace_insert ON public.%I FOR INSERT TO dong_a_workspace_scope WITH CHECK (%s)', t, rule);
        EXECUTE format('CREATE POLICY workspace_update ON public.%I FOR UPDATE TO dong_a_workspace_scope USING (%s) WITH CHECK (%s)', t, rule, rule);
        EXECUTE format('CREATE POLICY workspace_delete ON public.%I FOR DELETE TO dong_a_workspace_scope USING (%s)', t, rule);
    END LOOP;
END $$;
GRANT USAGE, SELECT ON SEQUENCE public.hk_world_rooms_id_seq TO dong_a_workspace_scope;
-- bảng nghiệp vụ mới: dữ liệu bị xóa (kể cả CASCADE khi xóa lớp / trường) được lưu một năm như các bảng khác
SELECT public.app_install_delete_archives();

