-- Nhiệm vụ thế giới khối của 4 chặng phần 3 (thêm khóa world, giữ nguyên các phần khác của nội dung)
UPDATE public.hk_saga_stages SET content = content || jsonb_build_object('world', $w${"title":"Chuẩn bị đón giặc","intro":"Cuối năm 1287, quân Nguyên chuẩn bị sang lần thứ ba. Em là một tiểu tướng trẻ (nhân vật hư cấu) cùng các bạn trong lớp nghe lệnh, dựng chiến lũy ở cửa ải rồi tới đài chỉ huy ở cửa sông nhận lời dặn của Hưng Đạo vương.","steps":[{"type":"talk","npc":"vua","goal":"Vào sân điện Thăng Long gặp vua Trần Nhân Tông.","lines":["Giặc Nguyên lại sắp sang. Trẫm đã đại xá thiên hạ; nhiều người vừa được tha xin tòng quân đánh giặc.","Hãy cùng họ chia nhau giữ những nơi hiểm yếu."]},{"type":"talk","npc":"tong_quan","goal":"Gặp người vừa được tha đang xin tòng quân.","lines":["Tôi được tha tội, nay xin theo quân giữ nước.","Cửa ải phía bắc cần chiến lũy. Ta đi lấy gỗ và tre thôi!"]},{"type":"gather","res":"go","count":4,"goal":"Vào rừng lấy 4 gỗ: đứng cạnh cây rồi chạm vào cây."},{"type":"gather","res":"tre","count":4,"goal":"Lấy 4 tre ở các bụi tre gần làng."},{"type":"craft","item":"rao","count":3,"goal":"Tới một bàn chế tạo, làm 3 rào chắn (mỗi rào 1 gỗ + 1 tre)."},{"type":"place","item":"rao","zone":"ai","count":3,"team":6,"goal":"Dựng rào chắn ở cửa ải phía bắc: em dựng 3, cả lớp cần đủ 6.","clue":"Cửa ải ở cuối con đường đất đi lên núi phía bắc Thăng Long."},{"type":"talk","npc":"hung_dao","goal":"Tới đài chỉ huy ở cửa sông báo tin cho Hưng Đạo vương.","lines":["Quân Nguyên chia ba cánh: một cánh từ Vân Nam xuống, đại quân của Thoát Hoan vào biên giới đông bắc, thủy quân của Ô Mã Nhi và Phàn Tiếp đi đường biển, theo sau là đoàn thuyền lương của Trương Văn Hổ.","Ta đã tâu với vua: “Thế giặc năm nay dễ phá.”","Riêng đường biển, Nhân Huệ vương Trần Khánh Dư được giao giữ Vân Đồn."]},{"type":"ask","npc":"hung_dao","goal":"Trả lời câu hỏi của Hưng Đạo vương.","prompt":"Quân Nguyên lần này tiến sang theo mấy đường?","options":[{"id":"a","text":"Một đường bộ qua biên giới phía bắc"},{"id":"b","text":"Hai đường: đường bộ và đường biển"},{"id":"c","text":"Ba đường: từ Vân Nam, qua biên giới đông bắc và theo đường biển"}],"correct":"c","right":"Đúng. Đường biển còn có cả đoàn thuyền lương theo sau, nên giữ Vân Đồn là việc rất hệ trọng.","wrong":"Chưa đúng. Nhớ lại lời ta vừa nói về các cánh quân của giặc."}]}$w$::jsonb) WHERE code = 'chuan-bi-1287' AND NOT (content ? 'world');
UPDATE public.hk_saga_stages SET content = content || jsonb_build_object('world', $w${"title":"Trinh sát đoàn thuyền lương","intro":"Thủy quân Ô Mã Nhi đã vượt qua Vân Đồn. Trần Khánh Dư bị hỏi tội và xin lập công chuộc tội. Em cùng các bạn giúp ông quan sát mặt biển, đóng thuyền nhẹ và đón đánh đoàn thuyền lương của giặc.","steps":[{"type":"talk","npc":"khanh_du","goal":"Qua cầu sang đảo Vân Đồn gặp Nhân Huệ vương Trần Khánh Dư.","lines":["Ta để thủy quân giặc vượt qua nên bị Thượng hoàng sai sứ hỏi tội. Ta xin khất vài ngày để lập công chuộc tội.","Thuyền chiến đi trước thì thuyền lương ắt theo sau. Em lên chòi canh xem giúp ta."]},{"type":"zone","zone":"gac","goal":"Lên chòi canh trên đồi, quan sát mặt biển.","lines":["Từ chòi canh, em thấy thuyền chiến của giặc đã đi xa vào trong.","Phía sau, một đoàn thuyền chở nặng đang chậm chạp tiến về vùng biển Vân Đồn."]},{"type":"talk","npc":"linh_canh","goal":"Báo điều em thấy cho lính canh biển.","lines":["Đó là đoàn thuyền lương của Trương Văn Hổ! Thuyền nặng, đi chậm, đi sau xa đoàn thuyền chiến.","Ta cần thuyền nhẹ để áp sát chúng."]},{"type":"gather","res":"go","count":4,"goal":"Lấy 4 gỗ để đóng thuyền nhẹ."},{"type":"gather","res":"tre","count":2,"goal":"Lấy 2 tre."},{"type":"craft","item":"thuyen","count":2,"goal":"Tới bàn chế tạo, đóng 2 thuyền nhẹ (mỗi chiếc 2 gỗ + 1 tre)."},{"type":"place","item":"thuyen","zone":"ben","count":2,"team":4,"goal":"Đưa thuyền ra cầu tàu phía nam đảo: em đưa 2 chiếc, cả lớp cần 4 chiếc."},{"type":"ask","npc":"khanh_du","goal":"Trả lời câu hỏi của Trần Khánh Dư.","prompt":"Vì sao đánh đoàn thuyền lương lại quan trọng hơn đuổi theo thuyền chiến?","options":[{"id":"a","text":"Vì thuyền lương dễ đánh nên lập công nhanh"},{"id":"b","text":"Vì lần này giặc chở lương bằng đường biển; mất lương thì quân Nguyên đói, không đánh lâu được"},{"id":"c","text":"Vì thuyền chiến của giặc đã quay về nước"}],"correct":"b","right":"Đúng! Hai lần trước giặc bị đói vì “vườn không nhà trống”, lần này chúng trông cả vào thuyền lương. Đánh vào lương là đánh vào chỗ yếu nhất.","wrong":"Chưa đúng. Nghĩ xem quân giặc ở xa sẽ sống bằng gì nếu không có lương mang theo."},{"type":"battle","zone":"bien","goal":"Ra bờ biển phía nam đảo đón đánh đoàn thuyền lương."},{"type":"talk","npc":"khanh_du","goal":"Về báo công với Trần Khánh Dư.","lines":["Trương Văn Hổ thua to, đổ cả thóc xuống biển rồi bỏ chạy!","Mất lương, quân Nguyên từ nay mỗi ngày một quẫn bách. Đây là bước ngoặt của cuộc kháng chiến."]}]}$w$::jsonb) WHERE code = 'van-don' AND NOT (content ? 'world');
UPDATE public.hk_saga_stages SET content = content || jsonb_build_object('world', $w${"title":"Giặc cạn lương ở Vạn Kiếp","intro":"Đầu năm 1288, quân Nguyên lại vào Thăng Long nhưng không có lương. Ở trại tiền quân, em cùng các bạn giúp dân cất giữ lúa, nghe tin trinh sát và hiểu vì sao giặc phải tính đường rút.","steps":[{"type":"talk","npc":"tuong_tien_quan","goal":"Vào trại tiền quân gặp viên tướng chỉ huy.","lines":["Không thấy thuyền lương tới, Thoát Hoan phải bỏ Thăng Long về Vạn Kiếp. Giặc thiếu lương, đêm đêm bị ta tập kích, bệnh tật lan rộng.","Không để chúng cướp được hạt thóc nào của dân. Em ra làng giúp bà con."]},{"type":"talk","npc":"gia_lang","goal":"Ra làng ven sông gặp cụ trưởng làng.","lines":["Lúa ngoài đồng đã chín. Để lại đây thì giặc cướp mất.","Cháu gặt giúp làng, đóng bao rồi mang vào kho trong núi gần trại."]},{"type":"gather","res":"lua","count":6,"goal":"Gặt 6 lúa ngoài đồng."},{"type":"craft","item":"bao","count":3,"goal":"Đóng 3 bao lương ở bàn chế tạo (mỗi bao 2 lúa)."},{"type":"place","item":"bao","zone":"kho_nui","count":3,"team":6,"goal":"Mang bao lương vào kho trong núi: em cất 3 bao, cả lớp cần 6 bao."},{"type":"talk","npc":"trinh_sat","goal":"Gặp lính trinh sát vừa từ Vạn Kiếp trở về.","lines":["Tướng giặc bàn nhau: “Quân có thể về, không thể giữ.”","Chúng sắp rút: thủy quân theo đường sông ra biển, bộ binh theo đường bộ."]},{"type":"ask","npc":"tuong_tien_quan","goal":"Trả lời câu hỏi của viên tướng.","prompt":"Vì sao quân Nguyên không giữ được Thăng Long và phải tính đường rút?","options":[{"id":"a","text":"Vì kinh thành Thăng Long quá nhỏ"},{"id":"b","text":"Vì mất thuyền lương nên thiếu lương thực, lại liên tục bị tập kích, bệnh tật lan rộng"},{"id":"c","text":"Vì vua Nguyên gọi quân về đánh Nhật Bản"}],"correct":"b","right":"Đúng. Chiếm được kinh thành mà không có lương thì cũng không giữ nổi.","wrong":"Chưa đúng. Nhớ lại chuyện đoàn thuyền lương ở Vân Đồn."},{"type":"ask","npc":"tuong_tien_quan","goal":"Trả lời thêm một câu hỏi.","prompt":"Quân Nguyên rút về nước theo những ngả nào?","options":[{"id":"a","text":"Chỉ theo đường biển"},{"id":"b","text":"Thủy quân theo đường sông ra biển, bộ binh theo đường bộ"},{"id":"c","text":"Ở lại Vạn Kiếp chờ viện binh"}],"correct":"b","right":"Đúng. Hưng Đạo vương đã đoán được và cho đón đánh trên cả hai đường; thủy quân của Ô Mã Nhi sẽ phải đi qua sông Bạch Đằng.","wrong":"Chưa đúng. Hãy nhớ lời lính trinh sát."}]}$w$::jsonb) WHERE code = 'van-kiep-1288' AND NOT (content ? 'world');
UPDATE public.hk_saga_stages SET content = content || jsonb_build_object('world', $w${"title":"Bí mật lòng sông","intro":"Mùa xuân năm 1288, thủy quân Nguyên sẽ rút qua sông Bạch Đằng. Em cùng các bạn tìm hiểu con nước, lấy gỗ, đẽo cọc, đóng cọc khi nước rút và phối hợp theo tín hiệu. Thao tác được đơn giản hóa cho trò chơi; nhân vật của em là hư cấu.","steps":[{"type":"talk","npc":"lao_chai","goal":"Đi dọc bờ sông, hỏi lão chài về con nước.","lines":["Ở cửa sông này, nước triều lên xuống rất mạnh. Nước lên thì thuyền lớn đi lại dễ dàng; nước rút thì lòng sông lộ ra nhiều bãi.","Cháu ra xem dấu mực nước trên mấy tảng đá kia."]},{"type":"zone","zone":"moc","goal":"Quan sát dấu mực nước trên các tảng đá ven sông.","lines":["Trên đá có hai vệt: vệt cao là mức nước lúc triều lên, vệt thấp là lúc triều rút.","Hai mức nước cách nhau rất xa – đủ để những cây cọc dài chìm khuất khi nước lên."]},{"type":"talk","npc":"hung_dao","goal":"Tới đài chỉ huy gặp Hưng Đạo vương.","lines":["Giặc sẽ rút theo đường sông ra biển. Ta bày trận địa cọc ở cửa sông.","Cọc bằng gỗ lim và nhiều loại gỗ khác, đầu đẽo nhọn, đóng xuống lòng sông khi nước rút, cách nhau chừng một mét. Nước lên thì cọc chìm khuất.","Cọc không chặn ngang lạch sâu mà làm hẹp các dòng chảy. Hãy đi lấy gỗ."]},{"type":"gather","res":"go","count":6,"goal":"Vào rừng lấy 6 gỗ."},{"type":"gather","res":"tre","count":2,"goal":"Lấy 2 tre để làm bè chở cọc."},{"type":"craft","item":"coc","count":4,"goal":"Ở bàn chế tạo bên sông, đẽo 4 cọc nhọn (mỗi cọc 1 gỗ)."},{"type":"craft","item":"be","count":1,"goal":"Làm 1 bè chở cọc (2 tre)."},{"type":"place","item":"coc","zone":"baicoc","count":4,"team":10,"goal":"Khi nước rút, đóng cọc trên bãi bồi cửa sông: em đóng 4 cọc, cả lớp cần đủ 10 cọc.","clue":"Chỉ đóng được cọc khi nước triều rút – xem đồng hồ con nước ở góc màn hình."},{"type":"talk","npc":"nguyen_khoai","goal":"Gặp Nguyễn Khoái, chỉ huy quân Thánh Dực, nhận tín hiệu.","lines":["Ta chỉ huy quân Thánh Dực. Khi nước triều lên, thuyền nhẹ ra khiêu chiến rồi giả thua chạy để nhử giặc vào trận địa.","Nhìn cờ hiệu của ta mà làm."]},{"type":"zone","zone":"nhu","tide":"high","goal":"Khi nước lên, ra cầu tàu cùng thuyền nhẹ chuẩn bị nhử giặc.","lines":["Nước đã lên, bãi cọc chìm khuất dưới mặt sông.","Cờ hiệu phất lên: thuyền nhẹ lao ra khiêu chiến!"]},{"type":"battle","zone":"cua_song","goal":"Theo tín hiệu, ra cửa sông bước vào trận quyết chiến."},{"type":"ask","npc":"hung_dao","goal":"Giải thích với Hưng Đạo vương (câu 1/3).","prompt":"Tại sao phải giấu bãi cọc dưới nước?","options":[{"id":"a","text":"Để cọc gỗ không bị mục"},{"id":"b","text":"Để lúc nước lên cọc chìm khuất, giặc không biết mà đuổi vào; lúc nước rút thuyền giặc vướng cọc"},{"id":"c","text":"Để cá trong sông không làm hỏng cọc"}],"correct":"b","right":"Đúng. Giặc không nhìn thấy cọc nên mới dám đuổi theo vào trận địa.","wrong":"Chưa đúng. Nghĩ xem lúc nước lên mặt sông trông như thế nào."},{"type":"ask","npc":"hung_dao","goal":"Giải thích với Hưng Đạo vương (câu 2/3).","prompt":"Vì sao phải chờ đúng con nước?","options":[{"id":"a","text":"Nhử giặc lúc nước lên để thuyền chúng vượt qua bãi cọc; đánh lúc nước rút khi cọc trồi lên"},{"id":"b","text":"Vì quân Trần chỉ đánh được vào buổi sáng"},{"id":"c","text":"Vì lúc nước rút thuyền đi nhanh hơn"}],"correct":"a","right":"Đúng! Toàn thư chép: nhân lúc nước triều lên thì khiêu chiến rồi giả thua chạy; nước triều xuống, thuyền giặc vướng cọc hết.","wrong":"Chưa đúng. Nhớ lại hai vệt nước em đã thấy trên đá."},{"type":"ask","npc":"hung_dao","goal":"Giải thích với Hưng Đạo vương (câu 3/3).","prompt":"Đã có bãi cọc, vì sao vẫn cần nhiều lực lượng cùng phối hợp?","options":[{"id":"a","text":"Cọc chỉ làm hẹp dòng chảy, cản thuyền; phải có thuyền nhẹ khiêu chiến nhử giặc, thủy quân giao chiến và hai vua đem quân tiếp chiến mới thắng"},{"id":"b","text":"Vì cọc tự đánh chìm được thuyền giặc"},{"id":"c","text":"Không cần, chỉ có cọc là đủ"}],"correct":"a","right":"Đúng. Chiến thắng Bạch Đằng là sự phối hợp giữa địa hình, thủy triều, bãi cọc và sức mạnh của quân dân nhà Trần.","wrong":"Chưa đúng. Cọc không chặn ngang được lạch sâu – còn cần những ai nữa?"}]}$w$::jsonb) WHERE code = 'bach-dang' AND NOT (content ? 'world');
